pub use glory_render::NodeId;
use glory_render::{NodeIds, RuntimeId};
use std::{hint::black_box, time::Instant};
#[path = "children-before.rs"] mod before;
#[path = "../../../crates/render/src/memory/children.rs"] mod after;
trait Order: Default {
    fn insert(&mut self, id: NodeId, before: Option<NodeId>);
    fn remove(&mut self, id: NodeId);
    fn slice(&self) -> &[NodeId];
}
impl Order for before::Children {
    fn insert(&mut self, id: NodeId, before: Option<NodeId>) {
        let at = before.map_or(self.len(), |before| if self.first() == Some(&before) { 0 } else { self.iter().position(|&i| i == before).unwrap() });
        self.insert(at, id);
    }
    fn remove(&mut self, id: NodeId) {
        let at = if self.first() == Some(&id) { 0 } else if self.last() == Some(&id) { self.len()-1 } else { self.iter().position(|&i| i == id).unwrap() };
        self.remove(at);
    }
    fn slice(&self) -> &[NodeId] { self }
}
impl Order for after::Children {
    fn insert(&mut self, id: NodeId, before: Option<NodeId>) { self.insert_before(id, before); }
    fn remove(&mut self, id: NodeId) { self.remove_id(id); }
    fn slice(&self) -> &[NodeId] { self }
}
fn run<O: Order>(rows: &[NodeId], incoming: &[NodeId], expected: &[NodeId], scenario: &str) -> u128 {
    let mut children = O::default();
    for &id in rows { children.insert(id, None); }
    let start = Instant::now();
    match scenario {
        "append" => for &id in incoming { children.insert(black_box(id), None); },
        "prepend" => for &id in incoming { children.insert(black_box(id), Some(rows[0])); },
        "reverse" | "shuffle" => {
            let mut before = None;
            for &id in expected.iter().rev() { children.remove(id); children.insert(id,before); before=Some(id); }
        }
        "head-retire" => for &id in rows { children.remove(black_box(id)); },
        _=>unreachable!(),
    }
    let elapsed=start.elapsed().as_nanos();
    assert_eq!(children.slice(), expected);
    elapsed
}
fn main() {
    println!("count,scenario,repeat,version,nanoseconds");
    for count in [1000,10000,50000] {
        let mut ids = NodeIds::new(RuntimeId::new());
        let rows: Vec<_> = (0..count).map(|_|ids.allocate()).collect();
        let incoming: Vec<_> = (0..count).map(|_|ids.allocate()).collect();
        for scenario in ["append","prepend","reverse","shuffle","head-retire"] {
            let mut expected=rows.clone();
            match scenario {
                "append"=>expected.extend_from_slice(&incoming),
                "prepend"=>{expected.splice(..0,incoming.clone());},
                "reverse"=>expected.reverse(),
                "shuffle"=>{let mut seed=17u64; for index in (1..count).rev(){seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1); expected.swap(index,seed as usize%(index+1));}},
                _=>expected.clear(),
            }
            for repeat in 0..6 {
                let versions=if repeat%2==0 {["before","after"]} else {["after","before"]};
                for version in versions {
                    let ns=if version=="before"{run::<before::Children>(&rows,&incoming,&expected,scenario)}else{run::<after::Children>(&rows,&incoming,&expected,scenario)};
                    println!("{count},{scenario},{repeat},{version},{ns}");
                }
            }
        }
    }
}

